import { join } from "node:path";

import { Document, Presentation, Workbook } from "@ruxex/artifact-tool";

const outputIndex = process.argv.indexOf("--output-dir") + 1;
const outputDirectory = process.argv[outputIndex];
if (!outputDirectory) throw new Error("--output-dir is required");

const workbook = await Workbook.create();
const sheet = workbook.worksheets.add("Smoke");
sheet.getRange("A1:B2").values = [["Name", "Count"], ["Ada", 3]];
workbook.recalculate();
await workbook.inspect({ kind: "sheet", sheetName: "Smoke" });
await workbook.exportXlsx(join(outputDirectory, "smoke.xlsx"));

const document = await Document.create({ title: "Smoke Document" });
document.addHeading("Smoke Document", 1);
document.addParagraph("Generated by the local Ruxex artifact runtime.");
document.addTable([["Format", "Status"], ["DOCX", "Ready"]]);
await document.inspect();
await document.exportDocx(join(outputDirectory, "smoke.docx"));

const presentation = await Presentation.create({ title: "Smoke Presentation" });
const slide = presentation.addSlide({ layout: "title" });
slide.addText("Smoke Presentation", { role: "title" });
slide.addText("Generated by the local Ruxex artifact runtime.", { role: "body" });
slide.addTable([["Format", "Status"], ["PPTX", "Ready"]]);
slide.addShape("rect", { x: 10, y: 5, w: 2, h: 1 });
await presentation.inspect();
await presentation.exportPptx(join(outputDirectory, "smoke.pptx"));
